import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as s,o as a,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const C=JSON.parse('{"title":"Cursor CLI","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/cursor/cursor-cli.md","filePath":"zh/products/ai-coding/cursor/cursor-cli.md","lastUpdated":1787110548000}'),o={name:"zh/products/ai-coding/cursor/cursor-cli.md"};function r(d,t,n,l,c,h){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="cursor-cli" tabindex="-1">Cursor CLI <a class="header-anchor" href="#cursor-cli" aria-label="Permalink to &quot;Cursor CLI&quot;">​</a></h1><p>Cursor CLI 是同一套编程 Agent 的<strong>终端形态</strong>：交互会话，或给脚本 / CI 的 print 模式。二进制是 <strong><code>agent</code></strong>，不是 <code>cursor</code>，也不是 Origin CLI 的 <code>origin</code>。</p><blockquote><p>官方：<a href="https://cursor.com/docs/cli/overview" target="_blank" rel="noreferrer">CLI overview</a>、<a href="https://cursor.com/docs/cli/installation" target="_blank" rel="noreferrer">Installation</a>、<a href="https://cursor.com/docs/cli/using" target="_blank" rel="noreferrer">Using</a>、<a href="https://cursor.com/docs/cli/headless" target="_blank" rel="noreferrer">Headless</a>。</p><p>CI 复制粘贴配方留在 <a href="./cursor-cookbook.html#终端和-ci-里用-cursor-cli">Cookbook</a>。</p></blockquote><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><ul><li>macOS、Linux、WSL 或 Windows PowerShell</li><li>一个你愿意让它改的 git checkout</li><li>脚本 / CI：Dashboard 里的 <code>CURSOR_API_KEY</code></li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>读完本页你能：</p><ol><li>装好 <code>agent</code>，交互跑一轮</li><li>和编辑器一样切换 Agent / Plan / Ask</li><li>无头用 <code>-p</code>，真正要写盘再加 <code>--force</code></li><li>用 <code>&amp;</code> 交给 Cloud，并且不把 <code>agent</code> 和 <code>origin</code> 搞混</li></ol><hr><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># macOS, Linux, WSL</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://cursor.com/install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows PowerShell</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">irm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://cursor.com/install?win32=true&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> iex</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>找不到 <code>agent</code> 就把 <code>~/.local/bin</code> 加进 <code>PATH</code>（bash：<code>~/.bashrc</code>；zsh：<code>~/.zshrc</code>）。更新：<code>agent update</code>（默认会自动更新）。</p><h2 id="交互模式" tabindex="-1">交互模式 <a class="header-anchor" href="#交互模式" aria-label="Permalink to &quot;交互模式&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agent</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;refactor the auth module to use JWT tokens&quot;</span></span></code></pre></div><p>Agent 可以写、审、改代码。命令过来时你批准。</p><h3 id="模式" tabindex="-1">模式 <a class="header-anchor" href="#模式" aria-label="Permalink to &quot;模式&quot;">​</a></h3><p>和编辑器同一套。用斜杠命令、<code>Shift+Tab</code> 或 <code>--mode</code> 切换。</p><table tabindex="0"><thead><tr><th>模式</th><th>干什么</th><th>怎么开</th></tr></thead><tbody><tr><td><strong>Agent</strong></td><td>完整工具，做编码任务</td><td>默认</td></tr><tr><td><strong>Plan</strong></td><td>先设计；会问澄清问题</td><td><code>Shift+Tab</code>、<code>/plan</code>、<code>--plan</code>、<code>--mode=plan</code></td></tr><tr><td><strong>Ask</strong></td><td>只读探索</td><td><code>/ask</code>、<code>--mode=ask</code></td></tr></tbody></table><p>Debug Mode 是<strong>编辑器</strong>约束。不要编一个 CLI <code>--mode=debug</code>。</p><h3 id="会话附加能力-官方" tabindex="-1">会话附加能力（官方） <a class="header-anchor" href="#会话附加能力-官方" aria-label="Permalink to &quot;会话附加能力（官方）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>动作</th><th>怎么做</th></tr></thead><tbody><tr><td>交给 Cloud</td><td>消息前加 <code>&amp;</code></td></tr><tr><td>以前的对话</td><td><code>agent ls</code></td></tr><tr><td>最近一次</td><td><code>agent resume</code> 或 <code>agent --continue</code></td></tr><tr><td>指定 id</td><td><code>agent --resume=&quot;chat-id-here&quot;</code></td></tr><tr><td>审 diff</td><td><code>Ctrl+R</code>（再按 <code>i</code> 跟进）</td></tr><tr><td>换行</td><td><code>Shift+Enter</code>（tmux 里用 <code>Ctrl+J</code>）</td></tr><tr><td>退出</td><td><code>Ctrl+D</code> 两次</td></tr><tr><td><code>@</code> 文件 / 文件夹</td><td>和编辑器同一思路</td></tr><tr><td>压缩上下文</td><td><code>/summarize</code>（<code>/compress</code> 是别名）</td></tr><tr><td>Worktree</td><td><code>agent --worktree &quot;…&quot;</code>（名字可选；在 <code>~/.cursor/worktrees/</code> 下）</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 会话中途 → Cloud Agent</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">refactor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> and</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> comprehensive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests</span></span></code></pre></div><p>之后在 <a href="https://cursor.com/agents" target="_blank" rel="noreferrer">cursor.com/agents</a> 或手机上接着看。</p><p>沙箱：<code>/sandbox</code> 或 <code>--sandbox &lt;mode&gt;</code>（<code>enabled</code> / <code>disabled</code>）。设置会保留。Sudo：CLI 弹出遮罩密码框；<strong>模型看不到</strong>密码。</p><h2 id="非交互-ci" tabindex="-1">非交互 / CI <a class="header-anchor" href="#非交互-ci" aria-label="Permalink to &quot;非交互 / CI&quot;">​</a></h2><p>脚本和 CI 用 <strong>print 模式</strong>（<code>-p</code> / <code>--print</code>）。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CURSOR_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">your_api_key_here</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;find and fix performance issues&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;gpt-5&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;review these changes for security issues&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output-format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> text</span></span></code></pre></div><h3 id="p-会不会写文件" tabindex="-1"><code>-p</code> 会不会写文件？ <a class="header-anchor" href="#p-会不会写文件" aria-label="Permalink to &quot;\`-p\` 会不会写文件？&quot;">​</a></h3><p>脚本契约以专门的 <a href="https://cursor.com/docs/cli/headless" target="_blank" rel="noreferrer">Headless</a> 页为准：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 只提议 — 不改文件</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Add JSDoc comments to this file&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 不确认，直接落盘</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Refactor this code to use modern ES6+ syntax&quot;</span></span></code></pre></div><p><code>--force</code> 才是写开关。HTML 版 Headless 还写了别名 <strong><code>--yolo</code></strong>。该页的 <code>.md</code> 快照只点名 <code>--force</code>。</p><p><code>cli/using.md</code> 仍写 “Cursor has full write access in non-interactive mode.” CI 请跟 Headless，<strong>要改磁盘就加 <code>--force</code></strong>。</p><p>脚本用 <code>CURSOR_API_KEY</code> 认证。输出：<code>--output-format text</code>（<code>-p</code> 默认）、<code>json</code> 或 <code>stream-json</code>。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output-format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> text</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;Review recent changes and write feedback to review.txt&quot;</span></span></code></pre></div><h2 id="rules、mcp、acp" tabindex="-1">Rules、MCP、ACP <a class="header-anchor" href="#rules、mcp、acp" aria-label="Permalink to &quot;Rules、MCP、ACP&quot;">​</a></h2><p>CLI 从 <code>.cursor/rules</code> 加载和编辑器同一套 <a href="https://cursor.com/docs/rules" target="_blank" rel="noreferrer">rules</a>。也会读根目录 <strong><code>AGENTS.md</code></strong> 和 <strong><code>CLAUDE.md</code></strong>。</p><p>MCP 来自项目的 <strong><code>mcp.json</code></strong>（和编辑器同一批 server）。Cloud Agents 用 cursor.com/agents 上的<strong>团队</strong> MCP 列表 — 来源不同。</p><p>ACP：<code>agent acp</code> 把 Cursor CLI 当成 ACP server，走 <code>stdio</code>（JSON-RPC）。JetBrains 也走 ACP — <a href="https://cursor.com/docs/integrations/jetbrains" target="_blank" rel="noreferrer">JetBrains</a>。</p><h2 id="agent-和-origin" tabindex="-1"><code>agent</code> 和 <code>origin</code> <a class="header-anchor" href="#agent-和-origin" aria-label="Permalink to &quot;\`agent\` 和 \`origin\`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>二进制</th><th>产品</th><th>教程</th></tr></thead><tbody><tr><td><strong><code>agent</code></strong></td><td>编程 Agent（本页）</td><td>你在这里</td></tr><tr><td><strong><code>origin</code></strong></td><td>git forge CLI</td><td><a href="./origin.html">Origin</a></td></tr></tbody></table><p>不要跑完 <code>curl https://cursor.com/install</code> 还指望得到 git 托管。那次安装是 <strong><code>agent</code></strong>。</p><h2 id="什么时候用" tabindex="-1">什么时候用 <a class="header-anchor" href="#什么时候用" aria-label="Permalink to &quot;什么时候用&quot;">​</a></h2><ul><li>人已经在 tmux / SSH / CI 任务里</li><li>想要同一套 Rules / <code>AGENTS.md</code>，不想开 GUI</li><li>需要 worktree（<code>--worktree</code>），别让 Agent 改当前 checkout</li></ul><p>Tab、Inline Edit、Debug Mode 留在编辑器。<a href="./cloud-agents.html">Cloud Agents</a> 适合笔记本该睡觉的时候。调用方是<strong>你自己的</strong> TypeScript / Python 进程时用 <a href="./cursor-sdk.html">SDK</a>。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><table tabindex="0"><thead><tr><th>陷阱</th><th>正确做法</th></tr></thead><tbody><tr><td>终端里敲 <code>cursor</code></td><td>二进制是 <strong><code>agent</code></strong></td></tr><tr><td>CI 里 <code>agent -p</code> 文件没变</td><td>加 <strong><code>--force</code></strong>（Headless 页）</td></tr><tr><td>只信 <code>using.md</code> 的 “full write access”</td><td>跟 <strong>Headless</strong> + <code>--force</code></td></tr><tr><td>指望 Debug Mode</td><td>只有编辑器有</td></tr><tr><td>和 Origin CLI 搞混</td><td>forge 是 <code>origin</code></td></tr><tr><td>交给 Cloud 却忘了 <code>&amp;</code></td><td><code>&amp; refactor …</code></td></tr><tr><td>以为用的是 Cloud 团队 MCP</td><td>CLI 读的是<strong>项目 <code>mcp.json</code></strong></td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./cursor-cookbook.html#终端和-ci-里用-cursor-cli">Cookbook · CLI</a> — CI 片段</li><li><a href="./cloud-agents.html">Cloud Agents</a> — <code>&amp;</code> 的落点</li><li><a href="./cursor-sdk.html">Cursor SDK</a> — 同一 Agent，进进程</li><li>官方：<a href="https://cursor.com/docs/cli/overview" target="_blank" rel="noreferrer">Overview</a>、<a href="https://cursor.com/docs/cli/installation" target="_blank" rel="noreferrer">Installation</a>、<a href="https://cursor.com/docs/cli/using" target="_blank" rel="noreferrer">Using</a>、<a href="https://cursor.com/docs/cli/headless" target="_blank" rel="noreferrer">Headless</a></li></ul>`,48)])])}const b=e(o,[["render",r]]);export{C as __pageData,b as default};
